import { NextResponse } from 'next/server';
import { spawn } from 'child_process';
import path from 'path';

export async function POST(request: Request) {
  try {
    const { message } = await request.json();

    if (!message) {
      return NextResponse.json(
        { error: 'Message is required' },
        { status: 400 }
      );
    }

    // Create a Python process to run the orchestrator
    const pythonProcess = spawn('python', [
      path.join(process.cwd(), 'backend', 'test_simple.py'),
      message
    ]);

    return new Promise((resolve, reject) => {
      let result = '';
      let error = '';

      pythonProcess.stdout.on('data', (data) => {
        result += data.toString();
      });

      pythonProcess.stderr.on('data', (data) => {
        error += data.toString();
      });

      pythonProcess.on('close', (code) => {
        if (code !== 0) {
          console.error('Python process error:', error);
          resolve(NextResponse.json(
            { 
              success: false,
              response: "I apologize, but I encountered an error while processing your request. Please try again.",
              agent_used: "None",
              agent_type: "error"
            },
            { status: 200 }
          ));
          return;
        }

        try {
          // Parse the Python script output
          const lines = result.split('\n');
          const success = lines.find(line => line.includes('Success:'))?.split(':')[1].trim() === 'True';
          const agentUsed = lines.find(line => line.includes('Agent Used:'))?.split(':')[1].trim();
          const response = lines.find(line => line.includes('Response:'))?.split(':')[1].trim();

          resolve(NextResponse.json({
            success,
            response,
            agent_used: agentUsed,
            agent_type: agentUsed?.toLowerCase().includes('rag') ? 'rag' : 'web'
          }));
        } catch (e) {
          console.error('Error parsing Python output:', e);
          resolve(NextResponse.json(
            { 
              success: false,
              response: "I apologize, but I encountered an error while processing your request. Please try again.",
              agent_used: "None",
              agent_type: "error"
            },
            { status: 200 }
          ));
        }
      });
    });
  } catch (error) {
    console.error('Error processing chat message:', error);
    return NextResponse.json(
      { 
        success: false,
        response: "I apologize, but I encountered an error while processing your request. Please try again.",
        agent_used: "None",
        agent_type: "error"
      },
      { status: 200 }
    );
  }
} 